from corgisim import scene, instrument, observation
from corgisim.scene import SimulatedImage
from corgisim.parallel_executor import run_parallel
from astropy.io import fits
from datetime import datetime
from functools import partial
import proper
import roman_preflight_proper
import pytest
import numpy as np
import glob
import os

# Same frames as test_observation_sequence.py, but generated by worker processes through frame_runner.
# allow_nesting=True so the zindex case can run PROPER (which opens its own pool) inside a worker.
N_JOBS = 2
frame_runner = partial(run_parallel, n_jobs=N_JOBS, allow_nesting=True)


@pytest.fixture(scope='module')
def setup():
    Vmag = 8
    sptype = 'G0V'
    cgi_mode = 'excam'
    bandpass_corgisim = '1F'
    cor_type = 'hlc_band1'
    cases = ['3e-8']
    rootname = 'hlc_ni_' + cases[0]
    host_star_properties = {'Vmag': Vmag, 'spectral_type': sptype, 'magtype': 'vegamag'}
    dm1 = proper.prop_fits_read( roman_preflight_proper.lib_dir + '/examples/'+rootname+'_dm1_v.fits' )
    dm2 = proper.prop_fits_read( roman_preflight_proper.lib_dir + '/examples/'+rootname+'_dm2_v.fits' )

    optics_keywords ={'cor_type':cor_type, 'use_errors':2, 'polaxis':10, 'output_dim':51,\
                    'use_dm1':1, 'dm1_v':dm1, 'use_dm2':1, 'dm2_v':dm2,'use_fpm':1, 'use_lyot_stop':1,  'use_field_stop':1 }
    gain = 1000
    emccd_keywords ={'em_gain':gain, }

    base_scene = scene.Scene(host_star_properties)
    optics =  instrument.CorgiOptics(cgi_mode, bandpass_corgisim, optics_keywords=optics_keywords, if_quiet=True)
    detector = instrument.CorgiDetector( emccd_keywords, photon_counting=True)

    return base_scene, optics, detector, gain

def test_save_as_fits_parallel(setup, tmp_path):
    # Frames generated at the same time get the same wall-clock FTIMEUTC. When saved, each frame
    # gets the start time of its exposure instead, so every frame has its own L1 file.
    base_scene, optics, detector, gain = setup
    exp_time = 20
    n_frames = 3

    satellite_spots_frame_time = 10
    satellite_spots_number_of_frames = 2
    detector_satspots = instrument.CorgiDetector( {'em_gain':500})
    satspot_keywords = {'num_pairs':2, 'sep_lamD': 7, 'angle_deg': [0,90], 'contrast': 1e-5}

    simulatedImage_list = observation.generate_observation_sequence(base_scene, optics, detector, exp_time, n_frames,
                                                                    satspots_are_present = True, satspots_detector = detector_satspots, satspots_exptime = satellite_spots_frame_time, satspots_number_of_frames = satellite_spots_number_of_frames, satspot_keywords = satspot_keywords,
                                                                    save_as_fits=True, output_dir=str(tmp_path), full_frame=True, loc_x=300, loc_y=300, frame_runner=frame_runner)

    n_total = n_frames + 3*satellite_spots_number_of_frames
    assert len(glob.glob(os.path.join(str(tmp_path), '*.fits'))) == n_total

    filenames = [sim_image.image_on_detector[0].header['FILENAME'] for sim_image in simulatedImage_list]
    assert len(set(filenames)) == n_total

    # FTIMEUTC steps by the exposure time of the frame before: satspot frames, then science frames
    ftimes = [datetime.fromisoformat(sim_image.image_on_detector[1].header['FTIMEUTC']) for sim_image in simulatedImage_list]
    steps = [(t1 - t0).total_seconds() for t0, t1 in zip(ftimes[:-1], ftimes[1:])]
    expected_steps = [satellite_spots_frame_time] * (3*satellite_spots_number_of_frames) + [exp_time] * (n_frames - 1)
    assert steps == pytest.approx(expected_steps)

if __name__ == '__main__':
    pytest.main([__file__, '-v'])
